#!/usr/bin/env bash
# 030 -- so leitura: o teste do convite por WhatsApp (person/tests/test_colaborador_sem_email) falha na base 1.0.274 tambem?
# 3 rodadas na copia do instalado (base) e 3 com o pacote 275, para ver se e acaso (token aleatorio) ou deterministico.
set -u
exec 2>&1
T=$(mktemp -d /tmp/t.XXXX); echo "" | base64 -d > $T/p.patch
for lado in base 275; do
  rm -rf $T/repo; mkdir -p $T/repo; (cd /opt/PMS-Banana-AI && tar cf - --exclude=.venv --exclude=__pycache__ --exclude='*.pyc' --exclude=node_modules SISTEMA 2>/dev/null) | (cd $T/repo && tar xf -)
  [ $lado = 275 ] && (cd $T/repo && patch -p1 -s --no-backup-if-mismatch < $T/p.patch)
  echo "== $lado ($(grep -oP 'VERSAO = "\K[^"]+' $T/repo/SISTEMA/api/app/versao.py))"
  for i in 1 2 3; do (cd $T/repo/SISTEMA && env -i PATH=/usr/bin:/bin HOME=$T LANG=C.UTF-8 PYTHONDONTWRITEBYTECODE=1 /opt/PMS-Banana-AI/SISTEMA/.venv/bin/pytest -o addopts="-p no:cacheprovider" -q api/app/person/tests/test_colaborador_sem_email.py 2>&1 | tail -1); done
done
grep -rn "convite:" /opt/PMS-Banana-AI/SISTEMA/api/app/person/*.py | head -5 | cut -c1-200
rm -rf $T
